Emitter(Point)

Requires(
	vec2 position;
	vec2 velocity;
)

Params(
	@position
	vec2 position;

	@range(min=0, step=0.1)
	float min_speed;
	float max_speed;

	@range(step = 0.0174533)
	@arc(at=position, to=max_angle, inner=min_speed, outer=max_speed)
	float min_angle;
	@range(step = 0.0174533)
	float max_angle;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position = params.position;
	float speed = rand_range(params.min_speed, params.max_speed);
	float angle = rand_range(params.min_angle, params.max_angle);
	particle.velocity = unit_vec(angle) * speed;
}

Emitter(Lifetime)

Requires(
	float lifetime;
)

Params(
	@range(min=0, step=0.1)
	float min_lifetime;
	float max_lifetime;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.lifetime = rand_range(params.min_lifetime, params.max_lifetime);
}

Affector(Age)

Requires(
	float lifetime;
)

Params(
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.lifetime -= ctx.dt;
}

Affector(Wind)

Requires(
	vec2 velocity;
)

Params(
	@vector(scale = 1)
	vec2 velocity;

	@range(min = 0, step = 0.1)
	float drag;

	@range(min = 0, max = 1, step = 0.01)
	float gustiness;
	@range(min = 0, step = 0.1)
	float gust_frequency;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// rand() is reseeded per particle each frame, so this is a stable phase
	float phase = rand() * TAU;
	float gust = sin(ctx.time * params.gust_frequency + phase) * 0.6
						 + sin(ctx.time * params.gust_frequency * 2.33 + phase * 1.7) * 0.4;
	vec2 wind = params.velocity * (1.0 + params.gustiness * gust);
	particle.velocity += (wind - particle.velocity) * min(params.drag * ctx.dt, 1.0);
}

Affector(Flutter)

Requires(
	vec2 velocity;
)

Params(
	@range(min = 0, step = 0.1)
	float strength;

	@range(min = 0, step = 0.1)
	float frequency;

	@range(min = 0, max = 1, step = 0.01)
	float variation;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// rand() is reseeded per particle each frame: stable phase/rate per flake
	float phase = rand() * TAU;
	float freq	= params.frequency * mix(1.0, 0.5 + rand(), params.variation);
	float amp	 = params.strength	* mix(1.0, 0.5 + rand(), params.variation);
	particle.velocity.x += sin(ctx.time * freq + phase) * amp * ctx.dt;
}

Affector(Fan)

Requires(
	vec2 position;
	vec2 velocity;
)

Params(
	@position
	vec2 position;

	@range(min = 0, step = 0.1)
	float strength;

	@range(min = 0, step = 0.1)
	float min_range;
	@range(min = 0, step = 0.1)
	float max_range;

	@range(step = 0.0174533)
	@arc(at = position, to = max_angle, inner = min_range, outer = max_range)
	float min_angle;
	@range(step = 0.0174533)
	float max_angle;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	vec2 d = particle.position - params.position;
	float dist = length(d);
	if (dist <= 0.0 || dist >= params.max_range) { return; }

	float mid = (params.min_angle + params.max_angle) * 0.5;
	float half_spread = (params.max_angle - params.min_angle) * 0.5;
	vec2 dir = d / dist;
	if (half_spread < PI && dot(dir, unit_vec(mid)) < cos(half_spread)) {
			return;
	}

	float falloff = 1.0 - smoothstep(params.min_range, params.max_range, dist);
	particle.velocity += dir * params.strength * falloff * ctx.dt;
}

Affector(Integrate)

Requires(
	vec2 position;
	vec2 velocity;
)

Params(
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position += particle.velocity * ctx.dt;
}

Renderer(Circle)

Requires(
	vec2 position;
	float lifetime;
)

Params(
	@range(min = 0, step = 0.1)
	float radius;

	@range(min = 0, step = 0.1)
	float glow;

	@color
	uint start_color;

	@color
	uint end_color;
)

Varying(0) vec2 v_p;
Varying(1) vec2 v_half_size;

// The glow skirt never reaches zero: pad the quad by several falloffs and
// window the skirt to zero at its edge (plus a small AA margin for the rim)
const float GLOW_PAD = 3.0;

#if GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_VERTEX

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	if (particle.lifetime > 0.0) {
		v_half_size = vec2(params.radius + params.glow * GLOW_PAD) * 1.05;
		v_p = sdf_quad(v_half_size);
		gl_Position = grain_transform * vec4(particle.position + v_p, 0.0, 1.0);
	} else {
		cull();
	}
}

#elif GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_FRAGMENT

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	float d = sd_circle(v_p, params.radius);

	vec2 q = clamp(abs(v_p) / v_half_size, 0.0, 1.0);
	float window = (1.0 - q.x * q.x) * (1.0 - q.y * q.y);

	// Crisp AA disc; the glow skirt takes over past the rim
	float a = max(
		sdf_mask(d),
		sdf_glow(d, max(params.glow, 0.0001)) * window
	);

	vec4 c = unpackUnorm4x8(params.start_color);
	vec4 c2 = unpackUnorm4x8(params.end_color);
	vec4 target_color = mix(c2, c, particle.lifetime / 6.0);
	target_color.a *= a;
	grain_Color = premultiply(target_color);
	grain_Color.a = 0.0;
}

#endif
